package com.own.promotion.coupon.dto;
public class MerchantCouponTemplateCommand { private String name,minimumAmount,discountAmount; private Integer totalQuantity; private Long claimStartsAt,claimEndsAt,expiresAt; public String getName(){return name;} public void setName(String v){name=v;} public Integer getTotalQuantity(){return totalQuantity;} public void setTotalQuantity(Integer v){totalQuantity=v;} public String getMinimumAmount(){return minimumAmount;} public void setMinimumAmount(String v){minimumAmount=v;} public String getDiscountAmount(){return discountAmount;} public void setDiscountAmount(String v){discountAmount=v;} public Long getClaimStartsAt(){return claimStartsAt;} public void setClaimStartsAt(Long v){claimStartsAt=v;} public Long getClaimEndsAt(){return claimEndsAt;} public void setClaimEndsAt(Long v){claimEndsAt=v;} public Long getExpiresAt(){return expiresAt;} public void setExpiresAt(Long v){expiresAt=v;} }
